//! Failure-first regressions for durable transaction, intent, and session replay boundaries.
use fugue::{git::{Entry,Git},journal,merge,round,session,util};
use serde_json::{json,Value};
use sha2::{Digest,Sha256};
use std::{collections::BTreeMap,fs,path::Path,process::Command};
fn repo()->(tempfile::TempDir,Git,String){let d=tempfile::tempdir().unwrap();assert!(Command::new("git").args(["init","-q","-b","main"]).arg(d.path()).status().unwrap().success());let g=Git::open(d.path()).unwrap();let e=Entry{kind:"file".into(),mode:0o100644,id:g.put_blob(b"base").unwrap()};let b=g.commit_tree(&g.put_tree(&BTreeMap::from([("a".into(),e)])).unwrap(),&[],"base").unwrap();g.advance("refs/heads/main",&b,None).unwrap();util::replace_leaf(&d.path().join("a"),Some(&util::Leaf{mode:0o100644,bytes:b"base".to_vec()})).unwrap();util::atomic_write(&d.path().join(".fugue/config"),&serde_json::to_vec(&json!({"round":{"id":"r1"},"actions":{"ok":{"argv":["/usr/bin/true"]}}})).unwrap()).unwrap();(d,g,b)}
fn target(g:&Git,b:&str)->(String,Value){let old=g.tree(b).unwrap()["a"].clone();let new=Entry{kind:"file".into(),mode:0o100644,id:g.put_blob(b"target").unwrap()};let t=g.commit_tree(&g.put_tree(&BTreeMap::from([("a".into(),new.clone())])).unwrap(),&[b.into()],"target").unwrap();let wal=json!({"t":"advance/begin","tx":"fixture","round":"r1","ref":"refs/heads/main","base":b,"commit":t,"changes":[{"path":"a","old":old,"new":new}]});(t,wal)}
fn history(r:&Path)->Vec<journal::Row>{journal::read(r,"round").unwrap()}
fn digest(body:&str)->String{format!("{:x}",Sha256::digest(body))[..16].into()}
fn split()->Value{json!([{"goal":"write result","ownedPaths":["result"],"deliverables":[{"path":"result","form":"file"}],"assertions":[{"name":"ok","action":"ok"}]}])}
#[test]fn wal_terminal_receipts_cannot_hide_or_reopen_an_unfinished_transaction(){for shape in ["orphan","wrong-round","duplicate-terminal","reused-id","overlapping"]{let(d,g,b)=repo();let(t,wal)=target(&g,&b);if shape!="orphan"{journal::append(d.path(),"round",wal.clone()).unwrap();}let mut end=json!({"t":"advance/end","tx":"fixture","round":"r1","recovered":false});if shape=="wrong-round"{end["round"]=json!("r2");}if shape!="overlapping"{journal::append(d.path(),"round",end.clone()).unwrap();}match shape{"duplicate-terminal"=>{journal::append(d.path(),"round",end).unwrap();},"reused-id"=>{journal::append(d.path(),"round",wal.clone()).unwrap();},"overlapping"=>{let mut second=wal;second["tx"]=json!("second");journal::append(d.path(),"round",second).unwrap();journal::append(d.path(),"round",end).unwrap();},_=>{}}let before=history(d.path());assert!(merge::recover(d.path()).is_err(),"accepted malformed {shape} receipt chain");assert_eq!(history(d.path()),before);assert_eq!(fs::read(d.path().join("a")).unwrap(),b"base");assert_eq!(g.resolve("main").unwrap(),Some(b));assert_ne!(g.resolve("main").unwrap(),Some(t));}}
#[test]fn interrupted_initial_intent_can_only_resume_the_same_pinned_goal(){let(d,g,b)=repo();let body=json!({"goal":"original goal"}).to_string();journal::append(d.path(),"round",json!({"t":"round/intent","round":"r1","base":b,"digest":digest(&body),"body":body})).unwrap();let before=history(d.path());assert!(round::command(d.path(),"plan",&["replacement goal".into()],&json!({"split":split()})).is_err(),"Idle crash prefix replaced the pinned intent");assert_eq!(history(d.path()),before);assert_eq!(g.resolve("main").unwrap(),Some(b.clone()));let plan=round::command(d.path(),"plan",&["original goal".into()],&json!({"split":split()})).unwrap();assert_eq!(plan["base"],b);assert_eq!(history(d.path()).iter().filter(|e|e.event["t"]=="round/intent").count(),1);}
#[test]fn duplicate_pinned_intents_fail_before_dispatch_or_archival(){let(d,g,b)=repo();round::command(d.path(),"plan",&["goal".into()],&json!({"split":split()})).unwrap();let intent=history(d.path()).iter().find(|e|e.event["t"]=="round/intent").unwrap().event.clone();journal::append(d.path(),"round",intent).unwrap();let before=history(d.path());assert!(round::command(d.path(),"go",&[],&json!({})).is_err(),"multiple pinned intents were accepted");assert_eq!(history(d.path()),before);assert_eq!(g.resolve("main").unwrap(),Some(b));assert!(g.resolve("refs/heads/agent/r1/1").unwrap().is_none());}
#[test]fn malformed_distill_replay_never_creates_an_understanding(){for shape in ["empty","nul","against-number","duplicate-session"]{let(d,_,_)=repo();let body=match shape{"empty"=>"","nul"=>"bad\0body",_=>"understanding"};let mut event=json!({"t":"holder/distill","round":"r1","agent":"round","session":"s1","digest":digest(body),"body":body});if shape=="against-number"{event["against"]=json!(123);}journal::append(d.path(),"round",event.clone()).unwrap();if shape=="duplicate-session"{event["against"]=event["digest"].clone();journal::append(d.path(),"round",event).unwrap();}let before=history(d.path());assert!(session::context(d.path(),"r1").is_err(),"accepted malformed {shape} distill");assert!(session::land_for(d.path(),"r1","understanding","s1").is_err());assert_eq!(history(d.path()),before);}}
#[test]fn archival_receipt_lookup_cannot_bypass_duplicate_or_invalid_role_replay(){for shape in ["duplicate","unknown-role","invalid-round"]{let(d,_,_)=repo();let round=if shape=="invalid-round"{"../escape"}else{"r1"};let role=if shape=="unknown-role"{"unknown"}else{"user"};let event=json!({"t":"session/message","round":round,"session":"s1","role":role,"body":"text"});journal::append(d.path(),"round",event.clone()).unwrap();if shape=="duplicate"{journal::append(d.path(),"round",event).unwrap();}let before=history(d.path());assert!(session::append_for(d.path(),round,role,"text","s1").is_err(),"receipt bypassed {shape} validation");assert_eq!(history(d.path()),before);}}
fn encode(seq:u64,event:Value)->Vec<u8>{let mut row=event.as_object().unwrap().clone();row.insert("seq".into(),seq.into());row.insert("writer".into(),json!("round"));let crc=format!("{:08x}",crc32fast::hash(util::canonical(&json!(row)).unwrap().as_bytes()));row.insert("crc".into(),json!(crc));let mut bytes=serde_json::to_vec(&row).unwrap();bytes.push(b'\n');bytes}
#[test]fn recovery_preflights_its_terminal_receipt_before_repairing_any_leaf(){let(d,g,b)=repo();let(t,wal)=target(&g,&b);journal::append(d.path(),"round",wal.clone()).unwrap();let mut bytes=encode(1,wal);let filler=json!({"t":"test/filler","body":""});let overhead=encode(2,filler.clone()).len();let body="x".repeat(util::MAX_BYTES-bytes.len()-overhead-16);bytes.extend(encode(2,json!({"t":"test/filler","body":body})));assert_eq!(bytes.len(),util::MAX_BYTES-16);fs::write(d.path().join(".fugue/log/round.jsonl"),&bytes).unwrap();g.advance("refs/heads/main",&t,Some(&b)).unwrap();assert!(merge::recover(d.path()).is_err(),"receipt should exceed the remaining journal capacity");assert_eq!(fs::read(d.path().join("a")).unwrap(),b"base","recovery mutated a leaf without capacity for a durable terminal receipt");assert_eq!(fs::read(d.path().join(".fugue/log/round.jsonl")).unwrap(),bytes);assert_eq!(g.resolve("main").unwrap(),Some(t));}
fn phase(r:&Path,a:&str,b:&str){journal::append(r,"round",json!({"t":"round/state","round":"r1","from":a,"to":b})).unwrap();}
fn completed(r:&Path,c:&Value,text:&str)->String{let w=c["agent"].as_str().unwrap();let mut v=fugue::view::View::load(r,w,None).unwrap();v.write("result",text.as_bytes(),None).unwrap();let ck=v.checkpoint("worker").unwrap();journal::append(r,w,json!({"t":"agent/stop","agent":w,"contract":c["id"],"reason":"end-turn","stopped":"done","steps":0})).unwrap();ck["commit"].as_str().unwrap().into()}
#[test]fn candidate_replay_must_match_completed_workers_before_any_verification_or_advance(){for shape in ["forged-tree","wrong-workers"]{let(d,g,b)=repo();let p=round::command(d.path(),"new",&["goal".into()],&json!({"split":split()})).unwrap();let worker=completed(d.path(),&p["contracts"][0],"worker result");let mut tree=g.tree(&worker).unwrap();if shape=="forged-tree"{tree.insert("outside-contract".into(),Entry{kind:"file".into(),mode:0o100644,id:g.put_blob(b"forged").unwrap()});}let t=g.put_tree(&tree).unwrap();let c=g.commit_tree(&t,std::slice::from_ref(&b),"candidate").unwrap();phase(d.path(),"Working","Collecting");phase(d.path(),"Collecting","Merging");let mut event=json!({"t":"merge/candidate","round":"r1","base":b,"tree":t,"commit":c});if shape=="wrong-workers"{event["workers"]=json!([b]);}journal::append(d.path(),"round",event).unwrap();phase(d.path(),"Merging","Verifying");let before=history(d.path());let refs=g.run(&["for-each-ref","--format=%(refname) %(objectname)"],None).unwrap();assert!(round::command(d.path(),"work",&[],&json!({"fail":"ok","retry":0})).is_err(),"accepted {shape} candidate");assert_eq!(history(d.path()),before);assert_eq!(g.run(&["for-each-ref","--format=%(refname) %(objectname)"],None).unwrap(),refs);assert!(!d.path().join("result").exists());assert!(!d.path().join("outside-contract").exists());}}
#[test]fn conflict_candidate_without_immutable_resolver_provenance_requires_review(){let(d,g,b)=repo();let p=round::command(d.path(),"new",&["goal".into()],&json!({"split":[split()[0].clone(),split()[0].clone()]})).unwrap();let cs=p["contracts"].as_array().unwrap();let workers=[completed(d.path(),&cs[0],"left\n"),completed(d.path(),&cs[1],"right\n")];let folded=merge::fold(&g,&b,&workers).unwrap();assert_eq!(folded["kind"],"conflict");let tree=g.put_tree(&g.tree(&workers[1]).unwrap()).unwrap();let candidate=g.commit_tree(&tree,std::slice::from_ref(&b),"legacy unproven conflict candidate").unwrap();phase(d.path(),"Working","Collecting");phase(d.path(),"Collecting","Merging");journal::append(d.path(),"round",json!({"t":"merge/candidate","round":"r1","base":b,"tree":tree,"commit":candidate})).unwrap();phase(d.path(),"Merging","Verifying");let before=history(d.path());let err=round::command(d.path(),"work",&[],&json!({"fail":"ok","retry":0})).unwrap_err();assert!(err.message.contains("review required"),"{err}");assert_eq!(history(d.path()),before);assert_eq!(g.resolve("main").unwrap(),Some(b));assert!(g.resolve("refs/heads/agent/r1/resolve-1").unwrap().is_none());assert!(!d.path().join("result").exists());}
#[test]fn changed_landing_symlink_cannot_alias_an_unchanged_unsafe_tree_link(){let(d,g,b)=repo();let mut base_tree=g.tree(&b).unwrap();let unsafe_link=Entry{kind:"symlink".into(),mode:0o120000,id:g.put_blob(b"/tmp/outside").unwrap()};base_tree.insert("legacy".into(),unsafe_link);let base=g.commit_tree(&g.put_tree(&base_tree).unwrap(),std::slice::from_ref(&b),"legacy link").unwrap();g.advance("refs/heads/main",&base,Some(&b)).unwrap();std::os::unix::fs::symlink("/tmp/outside",d.path().join("legacy")).unwrap();let mut target=base_tree;target.insert("alias".into(),Entry{kind:"symlink".into(),mode:0o120000,id:g.put_blob(b"legacy/child").unwrap()});target.get_mut("a").unwrap().id=g.put_blob(b"changed").unwrap();let c=g.commit_tree(&g.put_tree(&target).unwrap(),std::slice::from_ref(&base),"unsafe alias").unwrap();let before=history(d.path());assert!(merge::advance_verified(d.path(),"r1",&base,&c).is_err());assert_eq!(history(d.path()),before);assert_eq!(fs::read(d.path().join("a")).unwrap(),b"base");assert_eq!(fs::read_link(d.path().join("legacy")).unwrap(),Path::new("/tmp/outside"));assert!(!d.path().join("alias").exists());assert_eq!(g.resolve("main").unwrap(),Some(base));}
#[test]fn landing_graph_uses_real_untouched_symlinks_including_preserved_and_untracked_links(){for shape in ["preserved","unchanged","untracked"]{let(d,g,b)=repo();let mut base_tree=g.tree(&b).unwrap();if shape!="untracked"{base_tree.insert("legacy".into(),Entry{kind:"symlink".into(),mode:0o120000,id:g.put_blob(b"a").unwrap()});}let base=g.commit_tree(&g.put_tree(&base_tree).unwrap(),std::slice::from_ref(&b),"safe original link").unwrap();g.advance("refs/heads/main",&base,Some(&b)).unwrap();std::os::unix::fs::symlink("/tmp/outside",d.path().join("legacy")).unwrap();let mut target=base_tree;target.insert("alias".into(),Entry{kind:"symlink".into(),mode:0o120000,id:g.put_blob(b"legacy/child").unwrap()});target.get_mut("a").unwrap().id=g.put_blob(b"changed").unwrap();let c=g.commit_tree(&g.put_tree(&target).unwrap(),std::slice::from_ref(&base),"new alias").unwrap();let before=history(d.path());let preserve=if shape=="preserved"{vec!["legacy".into()]}else{vec![]};assert!(merge::advance_verified_with_preserve(d.path(),"r1",&base,&c,&preserve).is_err(),"new alias traversed {shape} outside disk link");assert_eq!(history(d.path()),before);assert_eq!(fs::read(d.path().join("a")).unwrap(),b"base");assert_eq!(fs::read_link(d.path().join("legacy")).unwrap(),Path::new("/tmp/outside"));assert!(!d.path().join("alias").exists());assert_eq!(g.resolve("main").unwrap(),Some(base));}}
#[test]fn graph_fallback_keeps_dangling_targets_and_replaced_old_symlink_topology_valid(){for shape in ["dangling","replace-old-link"]{let(d,g,b)=repo();let mut original=g.tree(&b).unwrap();if shape=="replace-old-link"{original.insert("node".into(),Entry{kind:"symlink".into(),mode:0o120000,id:g.put_blob(b"/tmp/outside").unwrap()});}let base=g.commit_tree(&g.put_tree(&original).unwrap(),std::slice::from_ref(&b),"original topology").unwrap();g.advance("refs/heads/main",&base,Some(&b)).unwrap();if shape=="replace-old-link"{std::os::unix::fs::symlink("/tmp/outside",d.path().join("node")).unwrap();}let mut next=original;let link=if shape=="dangling"{"missing/child"}else{next.remove("node");next.insert("node/child".into(),Entry{kind:"file".into(),mode:0o100644,id:g.put_blob(b"safe").unwrap()});"node/child"};next.insert("alias".into(),Entry{kind:"symlink".into(),mode:0o120000,id:g.put_blob(link.as_bytes()).unwrap()});let target=g.commit_tree(&g.put_tree(&next).unwrap(),std::slice::from_ref(&base),"safe target").unwrap();merge::advance_verified(d.path(),"r1",&base,&target).unwrap();assert_eq!(fs::read_link(d.path().join("alias")).unwrap(),Path::new(link));if shape=="replace-old-link"{assert_eq!(fs::read(d.path().join("alias")).unwrap(),b"safe");}assert_eq!(g.resolve("main").unwrap(),Some(target));}}
#[test]fn completed_worker_stop_cannot_authorize_a_later_unstopped_checkpoint(){let(d,g,b)=repo();let p=round::command(d.path(),"new",&["goal".into()],&json!({"split":split()})).unwrap();let c=&p["contracts"][0];completed(d.path(),c,"completed result");let mut v=fugue::view::View::load(d.path(),c["agent"].as_str().unwrap(),None).unwrap();v.write("result",b"later unstopped result",None).unwrap();v.checkpoint("after stop").unwrap();let before=history(d.path());assert!(round::command(d.path(),"work",&[],&json!({"fail":"ok","retry":0})).is_err(),"stale stop receipt authorized a later checkpoint");assert_eq!(history(d.path()),before);assert_eq!(g.resolve("main").unwrap(),Some(b));assert!(!d.path().join("result").exists());}
#[test]fn planning_revisions_keep_the_pinned_goal_and_invalidate_changed_draft_digests(){let(d,g,b)=repo();let first=round::command(d.path(),"plan",&["original goal".into()],&json!({"split":split()})).unwrap();let before=history(d.path());assert!(round::command(d.path(),"plan",&["replacement goal".into()],&json!({"split":split()})).is_err());assert_eq!(history(d.path()),before);let mut changed=split();changed[0]["ownedPaths"]=json!(["revised"]);changed[0]["deliverables"]=json!([{"path":"revised","form":"file"}]);let second=round::command(d.path(),"plan",&["original goal".into()],&json!({"split":changed})).unwrap();assert_ne!(first["version"]["digest"],second["version"]["digest"]);assert_eq!(history(d.path()).iter().filter(|r|r.event["t"]=="round/intent").count(),1);assert_eq!(g.resolve("main").unwrap(),Some(b));assert!(!history(d.path()).iter().any(|r|r.event["t"]=="round/approve"));}
